def gcd_multiple(numbers):
    return reduce(math.gcd, numbers)

def max_possible_gcd(N, A):
    current_gcd = gcd_multiple(A)
    for num in A:
        if num % current_gcd == 0:
            continue
        candidate = num * (current_gcd // math.gcd(num, current_gcd))
        if candidate <= 10**9:
            return candidate
    return current_gcd

