    max_prime_power = {p: 0 for p in primes}

    for num in numbers:
        temp_num = num
        for p in primes:
            count = 0
            while temp_num % p == 0:
                count += 1
                temp_num //= p
            if count > max_prime_power[p]:
                max_prime_power[p] = count

    # Check if there's a way to increase the gcd by replacing a number
    for i in range(n):
        original_num = numbers[i]
