def max_gcd_after_replacement():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    nums = list(map(int, data[1:]))

    prefix_lcm = [1] * n
    suffix_lcm = [1] * n

    for i in range(1, n):
        prefix_lcm[i] = lcm(prefix_lcm[i - 1], nums[i - 1])

    for i in range(n - 2, -1, -1):
        suffix_lcm[i] = lcm(suffix_lcm[i + 1], nums[i + 1])

    max_gcd = 0

    for i in range(n):
        if i == 0:
            current_gcd = suffix_lcm[i]
        elif i == n - 1:
            current_gcd = prefix_lcm[i]
        else:
            current_gcd = lcm(prefix_lcm[i - 1], suffix_lcm[i + 1])

        max_gcd = max(max_gcd, current_gcd)

    print(max_gcd)

